// Chin Ho Yiah 的假資料引擎 產出玩家端 API 的盤面
//
// 規則照 results-chinhoyiah.md
//   盤面    6 軸 x 5 列 每一格都計分 沒有隱藏列
//   計分    同符號在盤面任何位置共 8 顆以上中獎 8 到 9 10 到 11 12 以上三檔 沒有百搭
//   連消    中獎的格消除 上方的牌往下掉 空位從上方補新牌 SCATTER 與球不消除
//   球      符號 11 一個 id 面值放在格子標記 落下後面值不變
//   倍數    主遊戲有贏分時 終盤球面值和乘整轉贏分 免費遊戲跨轉累積
//   上限    5000 倍底注
//
// 跟後端不一樣的地方 觸發機率是固定值 加注只是提高觸發機率

import type { SlotApiBoard, SlotApiEvent, SlotApiWin } from '../SlotApiTypes';
import { getSlotApiDebugControl, randomInt } from './mock-shared';
import type { MockBoard, MockRound, MockRoundEngine, MockRoundOptions, MockSpin } from './types';

const COLS = 6;
const ROWS = 5;

const NORMAL_MIN = 1;
const NORMAL_MAX = 9;
const SCATTER_ID = 10;
// 後端的球只有一個符號 id 面值在格子標記
const BOOM_ID = 11;
// 引擎內部一個面值一個 id 輸出時換回 BOOM_ID
const BALL_MIN = 100;
const BALL_VALUES = [2, 3, 4, 5, 6, 8, 10, 12, 15, 20, 25, 50, 100, 250, 500, 1000];

// 賠付表 底注倍數的百分之一 [顆數門檻, 賠付]
const PAYS: Readonly<Record<number, ReadonlyArray<readonly [number, number]>>> = {
    1: [[8, 1000], [10, 2500], [12, 5000]],
    2: [[8, 250], [10, 1000], [12, 2500]],
    3: [[8, 200], [10, 500], [12, 1500]],
    4: [[8, 150], [10, 200], [12, 1200]],
    5: [[8, 100], [10, 150], [12, 1000]],
    6: [[8, 80], [10, 120], [12, 800]],
    7: [[8, 50], [10, 100], [12, 500]],
    8: [[8, 40], [10, 90], [12, 400]],
    9: [[8, 25], [10, 75], [12, 200]],
};
const SCATTER_PAYS: ReadonlyArray<readonly [number, number]> = [[4, 300], [5, 500], [6, 10000]];

const SCATTER_TRIGGER = 4;
const SCATTER_RETRIGGER = 3;
const FREE_SPINS = 15;
const RETRIGGER_SPINS = 5;
// 免費遊戲轉數的安全閥
const MAX_FREE_SPINS = 100;
const MAX_CASCADES = 8;
// 單局上限 底注倍數
const MAX_WIN_MULTIPLE = 5000;

const NATURAL_FREE_CHANCE = 0.08;
// 加注的觸發機率
const EXTRA_FREE_CHANCE = 0.14;
const MAIN_WIN_CHANCE = 0.4;
const FREE_WIN_CHANCE = 0.22;
// 中獎顆數 [顆數, 權重]
const CLUSTER_SIZES: ReadonlyArray<readonly [number, number]> = [[8, 0.7], [10, 0.25], [12, 0.05]];
// 一般符號 1 到 9 的出現權重 高賠符號少
const NORMAL_WEIGHTS = [3, 5, 7, 9, 13, 15, 17, 19, 22];
// 初盤的球數 [球數, 權重]
const BALL_COUNTS: ReadonlyArray<readonly [number, number]> = [[0, 0.68], [1, 0.25], [2, 0.06], [3, 0.01]];
const REFILL_BALL_CHANCE = 0.015;

// 球面值權重 與 BALL_VALUES 同順序 大面值很稀少
const BALL_WEIGHTS = [26, 22, 18, 12, 9, 6, 3.5, 1.6, 0.8, 0.4, 0.2, 0.08, 0.02, 0.004, 0.0008, 0.0002];

type Grid = number[][];

interface Cluster {
    symbol: number;
    // 格子位置 軸 x 5 + 列
    cells: number[];
    cents: number;
}

// 一轉的組裝選項
interface SpinPlan {
    kind: 'main' | 'free' | 'buy';
    // 這一轉要有連消贏分
    wantWin: boolean;
    forced?: { symbol: number; count: number };
    // 主遊戲這一轉觸發免費遊戲
    trigger: boolean;
    // 免費遊戲這一轉再觸發
    retrigger: boolean;
    // 免費遊戲跨轉累積倍數
    accBefore: number;
}

const position = (col: number, row: number): number => col * ROWS + row;
const isBallId = (id: number): boolean => id >= BALL_MIN && id < BALL_MIN + BALL_VALUES.length;
const ballValue = (id: number): number => BALL_VALUES[id - BALL_MIN] ?? 0;

// 十進位字串 底注倍數的百分之一轉底注倍數
function formatCents(cents: number): string {
    const whole = Math.floor(cents / 100);
    const fraction = String(cents % 100).padStart(2, '0').replace(/0+$/, '');
    return fraction ? `${whole}.${fraction}` : String(whole);
}

// 依權重挑一個
function pickWeighted<T>(items: ReadonlyArray<readonly [T, number]>): T {
    let roll = Math.random() * items.reduce((sum, [, weight]) => sum + weight, 0);
    for (const [item, weight] of items) {
        roll -= weight;
        if (roll < 0) return item;
    }
    return items[0][0];
}

function randomNormal(exclude?: number): number {
    let id = pickWeighted(NORMAL_WEIGHTS.map((weight, index): readonly [number, number] => [NORMAL_MIN + index, weight]));
    if (id === exclude) id = (id % NORMAL_MAX) + NORMAL_MIN;
    return id;
}

function randomBallId(): number {
    let roll = Math.random() * BALL_WEIGHTS.reduce((sum, weight) => sum + weight, 0);
    for (let i = 0; i < BALL_WEIGHTS.length; i++) {
        roll -= BALL_WEIGHTS[i];
        if (roll < 0) return BALL_MIN + i;
    }
    return BALL_MIN;
}

function shuffle<T>(items: readonly T[]): T[] {
    const out = Array.from(items);
    for (let i = out.length - 1; i > 0; i--) {
        const j = randomInt(i + 1);
        [out[i], out[j]] = [out[j], out[i]];
    }
    return out;
}

// 盤面所有位置
function scoringPositions(): number[] {
    const out: number[] = [];
    for (let col = 0; col < COLS; col++) for (let row = 0; row < ROWS; row++) out.push(position(col, row));
    return out;
}

const at = (grid: Grid, pos: number): number => grid[Math.floor(pos / ROWS)][pos % ROWS];
const put = (grid: Grid, pos: number, id: number): void => {
    grid[Math.floor(pos / ROWS)][pos % ROWS] = id;
};

function payFor(symbol: number, count: number): number {
    let pay = 0;
    for (const [min, cents] of PAYS[symbol] ?? []) if (count >= min) pay = cents;
    return pay;
}

function scatterPay(count: number): number {
    let pay = 0;
    for (const [min, cents] of SCATTER_PAYS) if (count >= min) pay = cents;
    return pay;
}

// 盤面上各個一般符號的中獎組
function evaluate(grid: Grid): Cluster[] {
    const bySymbol = new Map<number, number[]>();
    for (const pos of scoringPositions()) {
        const id = at(grid, pos);
        if (id < NORMAL_MIN || id > NORMAL_MAX) continue;
        (bySymbol.get(id) ?? bySymbol.set(id, []).get(id)!).push(pos);
    }
    const out: Cluster[] = [];
    bySymbol.forEach((cells, symbol) => {
        const cents = payFor(symbol, cells.length);
        if (cents > 0) out.push({ symbol, cells, cents });
    });
    return out;
}

function scatterPositions(grid: Grid): number[] {
    return scoringPositions().filter((pos) => at(grid, pos) === SCATTER_ID);
}

function ballPositions(grid: Grid): number[] {
    return scoringPositions().filter((pos) => isBallId(at(grid, pos)));
}

// 全隨機一般符號 保證沒有中獎
function plainGrid(): Grid {
    for (;;) {
        const grid: Grid = Array.from({ length: COLS }, () => Array.from({ length: ROWS }, () => randomNormal()));
        if (evaluate(grid).length === 0) return grid;
    }
}

// 把中獎組以外的格子換成不會中獎的隨機符號
function planGrid(plan: SpinPlan): Grid {
    const grid = plainGrid();
    const free = shuffle(scoringPositions());
    let cursor = 0;
    const take = (count: number): number[] => {
        const cells = free.slice(cursor, cursor + count);
        cursor += count;
        return cells;
    };

    if (plan.kind === 'buy' || plan.trigger) for (const pos of take(SCATTER_TRIGGER)) put(grid, pos, SCATTER_ID);
    else if (plan.retrigger) for (const pos of take(SCATTER_RETRIGGER)) put(grid, pos, SCATTER_ID);

    if (plan.wantWin) {
        const symbol = plan.forced?.symbol ?? randomNormal();
        const count = plan.forced?.count ?? pickWeighted(CLUSTER_SIZES);
        for (const pos of take(count)) put(grid, pos, symbol);
    }
    if (plan.kind !== 'buy') {
        const balls = pickWeighted(BALL_COUNTS);
        for (const pos of take(balls)) put(grid, pos, randomBallId());
    }
    return grid;
}

// 消除中獎格 倖存的牌往下掉 空位從上方補
function cascade(grid: Grid, clusters: readonly Cluster[]): Grid {
    const removed = new Set<number>(clusters.flatMap((cluster) => cluster.cells));
    return grid.map((column, col) => {
        const survivors = column.filter((_, row) => !removed.has(position(col, row)));
        const fills = Array.from({ length: ROWS - survivors.length }, () => (Math.random() < REFILL_BALL_CHANCE ? randomBallId() : randomNormal()));
        return [...fills, ...survivors];
    });
}

// 補牌後若又中獎 把多出來的符號換掉 避免超過連消上限
function repair(grid: Grid): Grid {
    for (const cluster of evaluate(grid)) {
        for (const pos of cluster.cells.slice(0, cluster.cells.length - 7)) put(grid, pos, randomNormal(cluster.symbol));
    }
    return evaluate(grid).length > 0 ? repair(grid) : grid;
}

function toRl(grid: Grid): number[][] {
    return grid.map((column) => column.map((id) => (isBallId(id) ? BOOM_ID : id)));
}

function toMarks(grid: Grid): SlotApiBoard['co'] {
    const marks: Record<string, { x: number }> = {};
    grid.forEach((column, col) =>
        column.forEach((id, row) => {
            if (isBallId(id)) marks[String(position(col, row))] = { x: ballValue(id) };
        })
    );
    return Object.keys(marks).length > 0 ? marks : undefined;
}

function clusterWin(cluster: Cluster): SlotApiWin {
    return { k: 'CL', sy: cluster.symbol, c: cluster.cells, p: formatCents(cluster.cents), w: formatCents(cluster.cents) };
}

// 組出一轉的所有盤面
function playSpin(plan: SpinPlan): { spin: MockSpin; accAfter: number } {
    let grid = planGrid(plan);
    const boards: MockBoard[] = [];
    let cascades = 0;
    let clusters = evaluate(grid);
    while (clusters.length > 0) {
        boards.push({
            board: {
                t: boards.length === 0 ? 'B' : 'C',
                rl: toRl(grid),
                co: toMarks(grid),
                wn: clusters.map(clusterWin),
                bm: formatCents(clusters.reduce((sum, cluster) => sum + cluster.cents, 0)),
                e: [{ t: 'WE' }],
            },
            paidCents: clusters.reduce((sum, cluster) => sum + cluster.cents, 0),
        });
        grid = cascade(grid, clusters);
        cascades++;
        if (cascades >= MAX_CASCADES) grid = repair(grid);
        clusters = evaluate(grid);
    }

    const cellsLinked = boards.reduce((sum, item) => sum + item.paidCents, 0);
    const scatters = scatterPositions(grid);
    const scatterCents = scatterPay(scatters.length);
    const balls = ballPositions(grid);
    const ballSum = balls.reduce((sum, pos) => sum + ballValue(at(grid, pos)), 0);
    const baseCents = cellsLinked + scatterCents;

    const wn: SlotApiWin[] = [];
    const events: SlotApiEvent[] = [];
    if (scatterCents > 0) wn.push({ k: 'SC', sy: SCATTER_ID, c: scatters, p: formatCents(scatterCents), w: formatCents(scatterCents) });

    if (wn.length > 0) events.push({ t: 'WE' });

    // 球倍數 有贏分且終盤有球才套用
    let accAfter = plan.accBefore;
    let multiplierCents = 0;
    if (ballSum > 0 && baseCents > 0) {
        if (plan.kind === 'free') {
            accAfter = plan.accBefore + ballSum;
            multiplierCents = baseCents * (accAfter - 1);
            events.push({ t: 'MA', d: { f: accAfter, ad: ballSum, c: balls, wa: formatCents(multiplierCents) } });
        } else {
            multiplierCents = baseCents * (ballSum - 1);
            events.push({ t: 'MA', d: { f: ballSum, c: balls, wa: formatCents(multiplierCents) } });
        }
    }

    let awarded = 0;
    if (plan.kind !== 'free' && scatters.length >= SCATTER_TRIGGER && plan.trigger) {
        awarded = FREE_SPINS;
        events.push({ t: 'FE', d: { rd: FREE_SPINS, sc: scatters } });
    } else if (plan.kind === 'free' && scatters.length >= SCATTER_RETRIGGER) {
        awarded = RETRIGGER_SPINS;
        events.push({ t: 'RT', d: { awd: RETRIGGER_SPINS, rsn: 'scatter', sc: scatters } });
    }

    const terminalCents = scatterCents + multiplierCents;
    boards.push({
        board: {
            t: boards.length === 0 ? 'B' : 'C',
            rl: toRl(grid),
            co: toMarks(grid),
            wn: wn.length > 0 ? wn : undefined,
            bm: terminalCents > 0 ? formatCents(terminalCents) : undefined,
            e: events.length > 0 ? events : undefined,
        },
        paidCents: terminalCents,
    });
    return { spin: { boards, awarded }, accAfter };
}

// 單局上限 超過就截斷並發 CA 免費遊戲到頂後不再打
export function applyCap(round: MockRound, capCents: number): void {
    let cumulative = 0;
    for (let s = 0; s < round.spins.length; s++) {
        const spin = round.spins[s];
        for (let b = 0; b < spin.boards.length; b++) {
            const item = spin.boards[b];
            const capped = item.paidCents;
            if (cumulative + capped <= capCents) {
                cumulative += capped;
                continue;
            }
            const allowed = Math.max(0, capCents - cumulative);
            item.paidCents = allowed;
            // CA 放在累計第一次超過上限的那一步 org 是截斷前的整局總額
            const original = cumulative + capped;
            const events = item.board.e ?? (item.board.e = []);
            events.push({ t: 'CA', d: { org: formatCents(original), cap: formatCents(capCents) } });
            const terminal = spin.boards[spin.boards.length - 1];
            const terminalEvents = terminal.board.e ?? [];
            if (s === 0) {
                // 主遊戲到頂 觸發的免費遊戲不開
                const index = terminalEvents.findIndex((event) => event.t === 'FE');
                if (index >= 0) {
                    terminalEvents[index] = { t: 'FB', d: { sc: terminalEvents[index].d?.sc } };
                    spin.awarded = 0;
                }
            } else {
                terminal.board.e = [...terminalEvents.filter((event) => event.t !== 'FX'), { t: 'FX', d: { rsn: 'cap_stop' } }];
            }
            for (let rest = b + 1; rest < spin.boards.length; rest++) spin.boards[rest].paidCents = 0;
            round.spins.length = s + 1;
            return;
        }
    }
}

function makeRound(options: MockRoundOptions = {}): MockRound {
    const control = getSlotApiDebugControl();
    const forced = control?.symbol_control;
    const hasControl = !!(forced || control?.win || control?.max_win);
    const buy = !!options.buy;
    const trigger = buy || (!hasControl && Math.random() < (options.extra ? EXTRA_FREE_CHANCE : NATURAL_FREE_CHANCE));

    const mainPlan: SpinPlan = {
        kind: buy ? 'buy' : 'main',
        wantWin: !buy && (!!forced || (!trigger && Math.random() < MAIN_WIN_CHANCE) || (trigger && Math.random() < 0.5)),
        forced: forced ? { symbol: forced.symbol, count: forced.count } : undefined,
        trigger,
        retrigger: false,
        accBefore: 0,
    };
    const main = playSpin(mainPlan);
    const round: MockRound = { spins: [main.spin] };

    if (main.spin.awarded > 0) {
        let remaining = main.spin.awarded;
        let acc = 0;
        while (remaining > 0 && round.spins.length <= MAX_FREE_SPINS) {
            const retrigger = Math.random() < 0.03;
            const freePlan: SpinPlan = {
                kind: 'free',
                wantWin: !!forced || Math.random() < FREE_WIN_CHANCE,
                forced: forced ? { symbol: forced.symbol, count: forced.count } : undefined,
                trigger: false,
                retrigger,
                accBefore: acc,
            };
            const result = playSpin(freePlan);
            acc = result.accAfter;
            round.spins.push(result.spin);
            remaining += result.spin.awarded - 1;
        }
        const last = round.spins[round.spins.length - 1].boards;
        last[last.length - 1].board.e = [...(last[last.length - 1].board.e ?? []), { t: 'FX', d: { rsn: 'spins_done' } }];
    }

    applyWinControl(round, control?.max_win ? { min: MAX_WIN_MULTIPLE + 1, max: MAX_WIN_MULTIPLE + 1 } : control?.win);
    applyCap(round, MAX_WIN_MULTIPLE * 100);
    return round;
}

// 治具指定整局贏分倍數 調整最後一張盤面的實付 只供假資料使用
function applyWinControl(round: MockRound, win: { min: number; max: number } | undefined): void {
    if (!win) return;
    const total = round.spins.reduce((sum, spin) => sum + spin.boards.reduce((s, item) => s + item.paidCents, 0), 0);
    const target = Math.round((win.min + Math.random() * (win.max - win.min)) * 100);
    const last = round.spins[round.spins.length - 1].boards;
    const tail = last[last.length - 1];
    tail.paidCents = Math.max(0, tail.paidCents + target - total);
    tail.board.bm = tail.paidCents > 0 ? formatCents(tail.paidCents) : undefined;
}

function makeDefaultBoard(): SlotApiBoard {
    return { t: 'B', rl: toRl(plainGrid()) };
}

export const chinHoYiahEngine: MockRoundEngine = {
    gameId: 'chinhoyiah',
    resultVersion: 2,
    baseBet: 20,
    rtp: '96.5',
    maxWinMultiple: MAX_WIN_MULTIPLE,
    buyOptions: [{ id: 'buy100', m: '100' }],
    extraOptions: [{ id: 'extra125', m: '1.25' }],
    makeDefaultBoard,
    makeRound,
};
