// 傳輸層與引擎共用的小工具

export type SlotApiDebugResultControl = {
    symbol_control?: { symbol: number; count: number; line?: number };
    win?: { min: number; max: number };
    max_win?: boolean;
};

// DebugPanel 寫在 globalThis 的治具 每局產生結果時才讀
export const getSlotApiDebugControl = (): SlotApiDebugResultControl | null => (globalThis as any).__slotApiDebugControl__ ?? null;

/**
 * 取 0 到 max−1 的隨機整數
 *
 * @param max 上界 不含
 * @returns 0 到 max−1 的整數
 */
export function randomInt(max: number): number {
    return Math.floor(Math.random() * max);
}
