import { Component, Graphics, Label, Layout, Mask, Node, RichText, Sprite, SpriteFrame, UIOpacity, UITransform, instantiate, sp } from 'cc';
import AppAssetBundle from '../../utils/AppAssetBundle';
import GameConfigManager from '../../config/GameConfigManager';
import type { BetHistoryDetail } from '../../models/BetHistory';
import type { SlotGrid } from '../../models/SlotGrid';
import { CURRENCY_MAP, GAMEVIEWMAP } from '../../store/StoreMap';
import { SLOT_GAME_DEFINITION } from '../../config/SlotGameDefinition';

export interface IconTableItem {
    symbol: string;
    col: number;
    row: number;
    multi?: string;
    amount?: string;
    type?: string;
}

const VISUAL_COMPONENT_CLASSES: Array<new (...args: any[]) => Component> = [UITransform, Sprite, Label, Layout, Mask, Graphics, UIOpacity, RichText, sp.Skeleton];

function isVisualComponent(comp: Component): boolean {
    return VISUAL_COMPONENT_CLASSES.some((cls) => comp instanceof cls);
}

export default class HistoryAdapter {
    private readonly symbolsFolder = 'resources/Images/Symbols';
    private readonly symbolCatalog = SLOT_GAME_DEFINITION.symbols;

    private static readonly VISIBLE_ROW_OFFSET = 2;

    async getTable(data: any): Promise<Node> {
        const prefab = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadPrefab(GAMEVIEWMAP.HISTORYTABLE.path);
        const node = instantiate(prefab) as Node;
        await this.fillTable(node, data);
        return node;
    }

    async getRoundDetail(data: BetHistoryDetail, isPortrait: boolean = false): Promise<Node> {
        const prefab = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadPrefab(GAMEVIEWMAP.HISTORYROUNDDETAIL.path);
        const root = instantiate(prefab) as Node;
        const portraitWidth = 700;
        const setWidth = (unit: Node) => {
            if (!isPortrait) return;
            const ut = unit.getComponent(UITransform);
            if (ut) ut.width = portraitWidth;
        };

        const grid = data.mainSteps[0]?.grid;
        const unit = await this.createNormalUnit(grid);
        setWidth(unit);
        this.setUnitWin(unit, data.summary.currency, data.summary.winAmount);
        root.addChild(unit);

        return root;
    }

    private async createNormalUnit(grid: SlotGrid | undefined): Promise<Node> {
        const unit = await this.loadRoundUnit();
        const tableContainer = unit.getChildByName('Table');
        const historyTable = tableContainer?.getChildByName('HistoryTable') ?? null;
        const historyBonusTable = tableContainer?.getChildByName('HistoryBonusTable') ?? null;
        if (historyBonusTable) historyBonusTable.active = false;
        if (historyTable) {
            historyTable.active = true;
            await this.fillGrid(historyTable, grid);
        }
        return unit;
    }

    private async loadRoundUnit(): Promise<Node> {
        const prefab = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadPrefab(GAMEVIEWMAP.HISTORYROUNDUNIT.path);
        return instantiate(prefab) as Node;
    }

    private setUnitWin(unit: Node, currency: any, win: any, titleText?: string): void {
        const label = unit.getChildByName('TotalWin')?.getComponent(Label);
        if (label) label.string = `${CURRENCY_MAP[currency] ?? ''}${win ?? 0}`;
        if (titleText !== undefined) {
            const title = unit.getChildByName('TotalWinTitle')?.getComponent(Label);
            if (title) title.string = titleText;
        }
    }

    private async fillTable(node: Node, data: BetHistoryDetail | null | undefined): Promise<void> {
        await this.fillIconTable(node, this.toHistoryIconTable(data?.mainSteps[0]?.grid));
    }

    private async fillGrid(node: Node, grid: SlotGrid | undefined): Promise<void> {
        await this.fillIconTable(node, this.toHistoryIconTable(grid));
    }

    private async fillIconTable(node: Node, table: IconTableItem[]): Promise<void> {
        this.stripLogicComponents(node);

        const slotMachineView = node.getChildByName('SlotMachineView');
        if (!slotMachineView) return;

        for (const item of table) {
            const imageName = item.symbol;
            if (!imageName) continue;

            const reel = slotMachineView.children[item.col];
            const container = reel?.getChildByName('Container');
            const posNode = container?.getChildByName(`pos${item.row + HistoryAdapter.VISIBLE_ROW_OFFSET}`);
            if (!posNode) continue;

            const spriteFrame = await this.getSprite(`${this.symbolsFolder}/${imageName}`);
            if (!spriteFrame) continue;
            // 等待期間節點可能已被銷毀
            if (!posNode.isValid) continue;

            for (const child of [...posNode.children]) child.destroy(); // 全刪除? TODO

            let sprite = posNode.getComponent(Sprite);
            if (!sprite) {
                sprite = posNode.addComponent(Sprite);
                sprite.sizeMode = Sprite.SizeMode.CUSTOM;
            }
            sprite.spriteFrame = spriteFrame;

            if (item.multi) await this.renderMultiplierLabel(posNode, item.multi); // 倍率球數值
        }
    }

    /** 倍率球數值顯示 1002 沒有倍率球 保留空實作 */
    private async renderMultiplierLabel(_posNode: Node, _multi: string): Promise<void> {}

    /** grid 已經是 SlotHistoryMapper 解碼過的 canonical 盤面，圖檔規則由遊戲 Catalog 提供。 */
    private toHistoryIconTable(grid: SlotGrid | null | undefined): IconTableItem[] {
        if (!grid) return [];
        return grid.columns.flatMap((column) =>
            column.symbolIds.map((symbolId, row) => ({
                symbol: this.symbolCatalog.frameName(symbolId),
                multi: this.resolveMulti(symbolId),
                col: column.index,
                row,
            }))
        );
    }

    /** 1002 沒有倍率球 一律不回傳 */
    private resolveMulti(_symbolId: number): string | undefined {
        return undefined;
    }

    private stripLogicComponents(node: Node): void {
        for (const comp of node.components.slice()) {
            if (!isVisualComponent(comp)) comp.destroy();
        }
        for (const child of node.children) {
            this.stripLogicComponents(child);
        }
    }

    private async getSprite(path: string): Promise<SpriteFrame | null> {
        const bundle = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).getBundle();
        return new Promise((resolve) => {
            bundle.load(`${path}/spriteFrame`, SpriteFrame, (err, asset) => {
                if (err) {
                    console.warn(`[HistoryAdapter] load sprite failed: ${path}`, err);
                    resolve(null);
                    return;
                }
                resolve(asset as SpriteFrame);
            });
        });
    }
}
