import { STEP_STATE, type SlotApiBoard, type SlotApiEvent, type SlotApiHistoryDetail, type SlotApiStep } from './SlotApiTypes';
import type {
    SlotAward,
    SlotFreeMultiplierStep,
    SlotFreeSpin,
    SlotResume,
    SlotRoundResult,
    SlotRoundStep,
    SlotRoundSteps,
} from '../models/SlotRound';
import type { SlotGridLayout } from '../models/SlotGrid';
import { SlotGridDecoder } from './SlotGridDecoder';
import { multiplyDecimal } from './SlotResponseAdapter';

// 事件代碼
const EVENT = {
    // 球倍數套用 f 實際乘上的倍數 ad 免費遊戲這一轉增加的面值和
    MULTIPLIER: 'MA',
    // 觸發免費遊戲 rd 授的轉數
    FREE_ENTERED: 'FE',
    // 湊滿 Scatter 但已到上限
    FREE_BLOCKED: 'FB',
    // 單局上限截斷 org 截斷前 cap 截斷後
    CAP: 'CA',
} as const;

// 中獎種類
const WIN_KIND = {
    CLUSTER: 'CL',
} as const;

/**
 * 從步驟編號取局號
 *
 * @param stepId 步驟編號 `{round_id}:{seq}:{index}`
 * @returns 第一個 `:` 前面那段
 */
export function roundIdOf(stepId: string): string {
    return stepId.split(':')[0];
}

// 玩家端盤面結果轉成前端模型的唯一轉換點 Handler Task View 不得直接讀 SlotApiTypes
// bet 每一步只帶一張盤面 所以贏分用那一步的 ctw 注單細單是一整轉 沒有逐步金額 改用 bm 乘底注
export class SlotRoundMapper {
    private readonly decoder: SlotGridDecoder;

    /**
     * @param layout 盤面形狀
     * @param amountScale 幣別小數位
     * @param currency 幣別
     */
    constructor(
        layout: SlotGridLayout,
        private readonly amountScale: number,
        private readonly currency: string
    ) {
        this.decoder = new SlotGridDecoder(layout);
    }

    /**
     * 主遊戲一轉轉成 SlotRoundResult 觸發免費遊戲時只帶授的轉數
     *
     * @param steps 這一轉的步驟 依交付順序
     * @param baseBet 底注金額
     * @returns 這一轉的結果
     * @throws 沒有步驟或沒有盤面時
     */
    toSlotRoundResult(steps: readonly SlotApiStep[], baseBet: string): SlotRoundResult {
        const first = steps[0];
        const last = steps[steps.length - 1];
        if (!first || !last) throw new RangeError('SlotRoundMapper.toSlotRoundResult: no steps');

        const mainSteps = this.toSteps(steps, baseBet);
        if (mainSteps.length === 0) throw new Error('主遊戲步驟沒有盤面');

        const events = this.eventsOf(steps);
        const entered = findEvent(events, EVENT.FREE_ENTERED);
        const freeSpinTriggered = !!entered || last.nst === STEP_STATE.FREE_SPIN;
        return {
            operationId: roundIdOf(first.sid),
            betId: first.sid,
            totalWin: last.tw,
            rawEngineWin: last.tw,
            engineWin: last.tw,
            maxWin: this.toMaxWin(events, baseBet),
            balanceAfter: last.bl,
            outcome: Number(last.tw) > 0 ? 'won' : 'lost',
            freeRound: false,
            chargedWager: first.tb,
            jackpot: { won: false, tier: '', payout: '0', currency: this.currency },
            mainSteps,
            freeRounds: [],
            freeSpinTriggered,
            freeMultipliers: [],
            multiplier: Number(findEvent(events, EVENT.MULTIPLIER)?.d?.f ?? 0) || 0,
            freeSpinsTotal: freeSpinTriggered ? toCount(entered?.d?.rd) || (last.fs?.ts ?? 0) : undefined,
            freeGameBlocked: !!findEvent(events, EVENT.FREE_BLOCKED),
        };
    }

    /**
     * 進場回應的最近一步 `ls` 轉成「進場要還原什麼」，entry 之後只呼叫一次（HttpClientStore.applyEntry）。
     *
     * 輸出分兩塊，使用端各自取用：
     * - `grid`：進場盤面，取 `ls.r.sg` 最後一張（連消到一半斷線時，最後一張才是停下來的那一步）。
     *   沒玩過或上一局已結束時是後端的預設盤面；`ls.r` 為 null 或 `sg` 為空時是 null，使用端退回隨機盤面。
     * - `freeGame`：只有 `ls.nst` 是 `STEP_STATE.FREE_SPIN` 且有 `ls.fs` 時才有（免費遊戲打到一半）。
     *   剩餘與總轉數取 `ls.fs`、累積倍數取 `ls.gs.am`（缺或不是數字時為 0）、贏分取 `ls.aw`。
     *   `result` 是收尾（ExitFreeGameTask）用的局資料，沒有任何盤面步驟，只有帳務欄位。
     *
     * 局打到一半（`isRoundInProgress(ls)`）但 `freeGame` 為 null，代表連消播到一半（`nst` 4／22）等還沒支援續打的狀態，
     * 使用端只畫盤面並印警告。
     *
     * 套用到其他遊戲時要對照各款自己的地方：
     * - 盤面解碼：本款 `decoder.decode` 收整張 `board`（球值在 `co`）；1001、1003 收 `board.rl`，照該款簽名傳。
     * - 累積倍數：`gs` 的鍵依各款 results 文件「延續狀態」節，本款是 `am`；沒有累積倍數的遊戲不用取。
     * - 本款沒有彩池，局資料沒有彩池落點欄位；有彩池的遊戲要補。
     * - 沒有免費遊戲的遊戲，`freeGame` 永遠是 null，可以整段拿掉。
     *
     * @param ls 進場回應的最近一步，永遠有值（沒玩過是後端合成的預設步驟）。
     * @returns 進場盤面與免費遊戲還原資料。
     * @throws 盤面格式不合（每軸列數對不上、球沒有標記或面值未登記等）時，由解碼器丟出；呼叫端要接住並退回隨機盤面。
     */
    toResume(ls: SlotApiStep): SlotResume {
        const boards = ls.r?.sg ?? [];
        const board = boards[boards.length - 1];
        const grid = board ? this.decoder.decode(board) : null;
        const fs = ls.fs;
        if (ls.nst !== STEP_STATE.FREE_SPIN || !fs) return { grid, freeGame: null };
        const accumulated = Number(ls.gs?.am ?? 0) || 0;
        const result: SlotRoundResult = {
            operationId: roundIdOf(ls.sid),
            betId: ls.sid,
            totalWin: ls.aw,
            rawEngineWin: ls.aw,
            engineWin: ls.aw,
            maxWin: { applied: false, multiplier: '', capAmount: '' },
            balanceAfter: ls.bl,
            outcome: Number(ls.aw) > 0 ? 'won' : 'lost',
            freeRound: false,
            chargedWager: ls.tb,
            jackpot: { won: false, tier: '', payout: '0', currency: this.currency },
            mainSteps: [],
            freeRounds: [],
            freeSpinTriggered: true,
            freeMultipliers: [],
            multiplier: 0,
            freeGameBlocked: false,
        };
        return { grid, freeGame: { total: fs.ts, remain: fs.s, accumulated, totalWin: ls.aw, result } };
    }

    /**
     * 免費遊戲一轉轉成 SlotFreeSpin
     *
     * @param steps 這一轉的步驟 依交付順序
     * @param baseBet 底注金額
     * @param accumulatedBefore 前面各轉累積的倍數 這一轉沒有球時沿用
     * @returns 這一轉的結果 轉數以最後一步的 fs 為準
     * @throws 沒有步驟時
     */
    toSlotFreeSpin(steps: readonly SlotApiStep[], baseBet: string, accumulatedBefore: number): SlotFreeSpin {
        const last = steps[steps.length - 1];
        if (!last) throw new RangeError('SlotRoundMapper.toSlotFreeSpin: no steps');

        const events = this.eventsOf(steps);
        const fs = last.fs;
        return {
            steps: this.toSteps(steps, baseBet),
            multiplier: this.toFreeMultiplier(events, last.tw, fs ? fs.ts - fs.s : 1, accumulatedBefore),
            remain: fs?.s ?? 0,
            total: fs?.ts ?? 0,
            finished: last.nst === STEP_STATE.BASE_SPIN,
            totalWin: last.aw,
            balance: last.bl,
            maxWinApplied: !!findEvent(events, EVENT.CAP),
        };
    }

    /**
     * 注單細單轉成 SlotRoundSteps 第一張是主遊戲 其餘是免費遊戲各轉
     *
     * @param details 細單 順序不拘 照 seq 排
     * @param baseBet 母單的底注金額
     * @returns 主遊戲與各轉免費遊戲的盤面 逐轉贏分與累積倍數
     */
    toRoundSteps(details: readonly SlotApiHistoryDetail[], baseBet: string): SlotRoundSteps {
        const sorted = Array.from(details).sort((a, b) => a.seq - b.seq);
        const [main, ...free] = sorted;
        const mainBoards = main?.result?.sg ?? [];
        const toSteps = (boards: readonly SlotApiBoard[]): SlotRoundStep[] => boards.map((board) => this.toStep(board, this.boardWin(board, baseBet), baseBet));

        let accumulated = 0;
        const freeMultipliers = free.map((detail, index) => {
            const events = (detail.result?.sg ?? []).flatMap((board) => board.e ?? []);
            const multiplier = this.toFreeMultiplier(events, detail.payout_amount, index + 1, accumulated);
            accumulated = multiplier.accumulated;
            return multiplier;
        });
        return {
            mainSteps: toSteps(mainBoards),
            freeRounds: free.map((detail) => toSteps(detail.result?.sg ?? [])),
            freeSpinTriggered: free.length > 0 || mainBoards.some((board) => findEvent(board.e ?? [], EVENT.FREE_ENTERED)),
            freeMultipliers,
            multiplier: Number(findEvent(mainBoards.flatMap((board) => board.e ?? []), EVENT.MULTIPLIER)?.d?.f ?? 0) || 0,
        };
    }

    // 每步只有一張盤面時贏分用 ctw 有好幾張時用各盤面的 bm 避免同一筆 ctw 算兩次 r 是 null 的步驟略過
    private toSteps(steps: readonly SlotApiStep[], baseBet: string): SlotRoundStep[] {
        return steps.flatMap((step) => {
            const boards = step.r?.sg ?? [];
            if (boards.length === 1) return [this.toStep(boards[0], step.ctw, baseBet)];
            return boards.map((board) => this.toStep(board, this.boardWin(board, baseBet), baseBet));
        });
    }

    // 只有全盤計數算 awards Scatter 不消除
    private toStep(board: SlotApiBoard, win: string, baseBet: string): SlotRoundStep {
        return {
            grid: this.decoder.decode(board),
            awards: (board.wn ?? [])
                .filter((entry) => entry.k === WIN_KIND.CLUSTER)
                .map(
                    (entry): SlotAward => ({
                        symbolId: entry.sy,
                        count: entry.c.length,
                        positions: entry.c.flatMap((position) => this.decoder.toCell(position) ?? []),
                        pay: multiplyDecimal(entry.w, baseBet, this.amountScale),
                    })
                ),
            win,
        };
    }

    // 沒有中獎的盤面不帶 bm 視為 0
    private boardWin(board: SlotApiBoard, baseBet: string): string {
        return multiplyDecimal(board.bm ?? '0', baseBet, this.amountScale);
    }

    private toMaxWin(events: readonly SlotApiEvent[], baseBet: string): SlotRoundResult['maxWin'] {
        const cap = findEvent(events, EVENT.CAP)?.d?.cap;
        if (cap === undefined) return { applied: false, multiplier: '', capAmount: '' };
        return { applied: true, multiplier: String(cap), capAmount: multiplyDecimal(String(cap), baseBet, this.amountScale) };
    }

    // 沒有 MA 時累積倍數不變
    private toFreeMultiplier(events: readonly SlotApiEvent[], win: string, round: number, accumulatedBefore: number): SlotFreeMultiplierStep {
        const applied = findEvent(events, EVENT.MULTIPLIER);
        const accumulated = applied ? Number(applied.d?.f ?? accumulatedBefore) || accumulatedBefore : accumulatedBefore;
        return { round, multiplier: Number(applied?.d?.ad ?? 0) || 0, accumulated, win };
    }

    private eventsOf(steps: readonly SlotApiStep[]): SlotApiEvent[] {
        return steps.flatMap((step) => (step.r?.sg ?? []).flatMap((board) => board.e ?? []));
    }
}

function findEvent(events: readonly SlotApiEvent[], type: string): SlotApiEvent | undefined {
    return events.find((e) => e.t === type);
}

// 事件裡的轉數欄位轉成非負整數
function toCount(value: unknown): number {
    const count = Number(value);
    return Number.isFinite(count) && count > 0 ? Math.floor(count) : 0;
}
